                    '\n'
                    '\n'
                    'let MENU = [];\n'
                    'let ORDERS = [];\n'
                    '\n'
                    'let editingId = null;\n'
                    '\n'
                    'let unsubscribeMenu = null;\n'
                    'let unsubscribeOrders = null;\n'
                    'let unsubscribeStats = null;\n'
                    'let unsubscribeStore = null;\n'
                    'let unsubscribePayment = null;\n'
                    '\n'
                    'let currentQrImageUrl = "";\n'
                    'let currentQrStoragePath = "";\n'
                    '\n'
                    '\n'
                    '/* =====================================\n'
                    '   FIREBASE\n'
                    '===================================== */\n'
                    '\n'
                    'if (!firebase.apps.length) {\n'
                    '\n'
                    '  firebase.initializeApp(\n'
                    '    self.FIREBASE_CONFIG\n'
                    '  );\n'
                    '\n'
                    '}\n'
                    '\n'
                    '\n'
                    'const auth =\n'
                    '  firebase.auth();\n'
                    '\n'
                    '\n'
                    'const db =\n'
                    '  firebase.firestore();\n'
                    '\n'
                    '\n'
                    'const storage =\n'
                    '  firebase.storage();\n'
                    '\n'
                    '\n'
                    'const functions =\n'
                    '  firebase\n'
                    '    .app()\n'
                    '    .functions(\n'
                    '      self.FIREBASE_FUNCTIONS_REGION ||\n'
                    '      "asia-southeast1"\n'
                    '    );\n'
                    '\n'
                    '\n'
                    'const testAdminPush =\n'
                    '  functions.httpsCallable(\n'
                    '    "testAdminPush"\n'
                    '  );\n'
                    '\n'
                    '\n'
                    'auth.setPersistence(\n'
                    '  firebase.auth.Auth.Persistence.LOCAL\n'
                    ');\n'
                    '\n'
                    '\n'
                    '/* =====================================\n'
                    '   AUTH\n'
                    '===================================== */\n'
                    '\n'
                    'function isAdminUser(user) {\n'
                    '\n'
                    '  return !!user\n'
                    '    &&\n'
                    '    String(\n'
                    '      user.email || ""\n'
                    '    ).toLowerCase()\n'
                    '    ===\n'
                    '    ADMIN_EMAIL.toLowerCase();\n'
                    '\n'
                    '}\n'
                    '\n'
                    '\n'
                    'function showLogin() {\n'
                    '\n'
                    '  $("loginPanel").hidden =\n'
                    '    false;\n'
                    '\n'
                    '  $("adminApp").hidden =\n'
                    '    true;\n'
                    '\n'
                    '  $("logoutBtn").hidden =\n'
                    '    true;\n'
                    '\n'
                    '}\n'
                    '\n'
                    '\n'
                    'function showAdmin() {\n'
                    '\n'
                    '  $("loginPanel").hidden =\n'
                    '    true;\n'
                    '\n'
                    '  $("adminApp").hidden =\n'
                    '    false;\n'
                    '\n'
                    '  $("logoutBtn").hidden =\n'
                    '    false;\n'
                    '\n'
                    '}\n'
                    '\n'
                    '\n'
                    'auth.onAuthStateChanged(\n'
                    '  async user => {\n'
                    '\n'
                    '    stopAdmin();\n'
                    '\n'
                    '\n'
                    '    if (\n'
                    '      isAdminUser(user)\n'
                    '    ) {\n'
                    '\n'
                    '      await user\n'
                    '        .getIdToken(true)\n'
                    '        .catch(console.error);\n'
                    '\n'
                    '\n'
                    '      showAdmin();\n'
                    '\n'
                    '      startAdmin();\n'
                    '\n'
                    '    } else {\n'
                    '\n'
                    '      showLogin();\n'
                    '\n'
                    '    }\n'
                    '\n'
                    '  }\n'
                    ');\n'
                    '\n'
                    '\n'
                    '/* =====================================\n'
                    '   LOGIN\n'
                    '===================================== */\n'
                    '\n'
                    '$("loginForm")\n'
                    '  .addEventListener(\n'
                    '    "submit",\n'
                    '    async event => {\n'
                    '\n'
                    '      event.preventDefault();\n'
                    '\n'
                    '\n'
                    '      $("loginMessage")\n'
                    '        .textContent =\n'
                    '        "Đang đăng nhập...";\n'
                    '\n'
                    '\n'
                    '      try {\n'
                    '\n'
                    '        const credential =\n'
                    '          await auth\n'
                    '            .signInWithEmailAndPassword(\n'
                    '              ADMIN_EMAIL,\n'
                    '              $("password").value\n'
