                    '\n'
                    '\n'
                    '        if (\n'
                    '          !isAdminUser(\n'
                    '            credential.user\n'
                    '          )\n'
                    '        ) {\n'
                    '\n'
                    '          await auth.signOut();\n'
                    '\n'
                    '          throw new Error(\n'
                    '            "Không có quyền Admin."\n'
                    '          );\n'
                    '\n'
                    '        }\n'
                    '\n'
                    '\n'
                    '        await credential.user\n'
                    '          .getIdToken(true);\n'
                    '\n'
                    '\n'
                    '        $("password").value =\n'
                    '          "";\n'
                    '\n'
                    '\n'
                    '        $("loginMessage")\n'
                    '          .textContent =\n'
                    '          "";\n'
                    '\n'
                    '      } catch (error) {\n'
                    '\n'
                    '        console.error(error);\n'
                    '\n'
                    '\n'
                    '        $("loginMessage")\n'
                    '          .textContent =\n'
                    '\n'
                    '          error.code ===\n'
                    '            "auth/invalid-credential"\n'
                    '\n'
                    '          ?\n'
                    '\n'
                    '          "Mật khẩu không đúng."\n'
                    '\n'
                    '          :\n'
                    '\n'
