                    '            "Không đăng nhập được."\n'
                    '          );\n'
                    '\n'
                    '      }\n'
                    '\n'
                    '    }\n'
                    '  );\n'
                    '\n'
                    '\n'
                    '$("logoutBtn")\n'
                    '  .addEventListener(\n'
                    '    "click",\n'
                    '    async () => {\n'
                    '\n'
                    '      stopAdmin();\n'
                    '\n'
                    '      await auth.signOut();\n'
                    '\n'
                    '    }\n'
                    '  );\n'
                    '\n'
                    '\n'
                    '/* =====================================\n'
                    '   START\n'
                    '===================================== */\n'
                    '\n'
                    'function startAdmin() {\n'
                    '  CCAdmin.start();\n'
                    '\n'
                    '  loadMenu();\n'
                    '\n'
                    '  loadOrders();\n'
                    '\n'
