                    '\n'
                    '  loadStoreSettings();\n'
                    '\n'
                    '  loadPaymentSettings();\n'
                    '\n'
                    '  updatePushUI();\n'
                    '\n'
                    '}\n'
                    '\n'
                    '\n'
                    'function stopAdmin() {\n'
                    '  CCAdmin.stop();\n'
                    '\n'
                    '  [\n'
                    '    unsubscribeMenu,\n'
                    '    unsubscribeOrders,\n'
                    '    unsubscribeStats,\n'
                    '    unsubscribeStore,\n'
                    '    unsubscribePayment\n'
                    '  ]\n'
                    '  .forEach(\n'
                    '    fn => {\n'
                    '\n'
                    '      if (\n'
                    '        typeof fn ===\n'
                    '        "function"\n'
                    '      ) {\n'
                    '\n'
                    '        fn();\n'
                    '\n'
                    '      }\n'
                    '\n'
                    '    }\n'
                    '  );\n'
                    '\n'
                    '\n'
                    '  unsubscribeMenu = null;\n'
                    '  unsubscribeOrders = null;\n'
                    '  unsubscribeStats = null;\n'
                    '  unsubscribeStore = null;\n'
                    '  unsubscribePayment = null;\n'
                    '\n'
                    '}\n'
                    '\n'
                    '\n'
                    '/* =====================================\n'
                    '   TABS\n'
                    '===================================== */\n'
                    '\n'
                    'document\n'
                    '  .querySelectorAll(\n'
                    '    ".tab-button"\n'
                    '  )\n'
                    '  .forEach(\n'
                    '    button => {\n'
                    '\n'
                    '      button.addEventListener(\n'
                    '        "click",\n'
                    '        () => {\n'
                    '\n'
                    '          document\n'
                    '            .querySelectorAll(\n'
                    '              ".tab-button"\n'
                    '            )\n'
                    '            .forEach(\n'
