                    '\n'
                    '\n'
                    '          button.classList\n'
                    '            .add(\n'
                    '              "active"\n'
                    '            );\n'
                    '\n'
                    '\n'
                    '          const page =\n'
                    '            $(\n'
                    '              "tab-" +\n'
                    '              button.dataset.tab\n'
                    '            );\n'
                    '\n'
                    '\n'
                    '          if (page) {\n'
                    '\n'
                    '            page.classList\n'
                    '              .add(\n'
                    '                "active"\n'
                    '              );\n'
                    '\n'
                    '          }\n'
                    '\n'
