                      '      </button>\n'
                      '\n'
                      '    </nav>\n'
                      '\n'
                      '\n'
                      '    <!-- =========================\n'
                      '         STATS\n'
                      '    ========================== -->\n'
                      '\n'
                      '    <section\n'
                      '      id="tab-stats"\n'
                      '      class="tab-page active"\n'
                      '    >\n'
                      '\n'
                      '      <div class="stats-grid">\n'
                      '\n'
                      '        <article class="stat-card">\n'
                      '\n'
