                      '              0\n'
                      '            </strong>\n'
                      '          </div>\n'
                      '\n'
                      '        </article>\n'
                      '\n'
                      '\n'
                      '        <article class="stat-card">\n'
                      '\n'
                      '          <div class="stat-icon">\n'
                      '            💰\n'
                      '          </div>\n'
                      '\n'
                      '          <div>\n'
                      '            <span>Giá trị đơn hôm nay</span>\n'
                      '\n'
                      '            <strong id="todayRevenue">\n'
                      '              0đ\n'
                      '            </strong>\n'
                      '          </div>\n'
                      '\n'
                      '        </article>\n'
                      '\n'
                      '      </div>\n'
                      '\n'
                      '\n'
                      '      <section class="panel">\n'
                      '\n'
                      '        <div class="section-head">\n'
                      '\n'
                      '          <div>\n'
                      '\n'
                      '            <div class="section-label">\n'
                      '              THỐNG KÊ\n'
                      '            </div>\n'
                      '\n'
                      '            <h2>\n'
                      '              Lịch sử giá trị đơn\n'
                      '            </h2>\n'
                      '\n'
                      '            <p class="muted">\n'
                      '              31 ngày gần nhất, gồm cả đơn chưa thanh toán. Báo cáo lãi phía trên chỉ '
                      'tính đơn đã trả.\n'
                      '            </p>\n'
                      '\n'
                      '          </div>\n'
                      '\n'
                      '        </div>\n'
                      '\n'
                      '\n'
                      '        <div class="table-wrap">\n'
                      '\n'
                      '          <table>\n'
                      '\n'
                      '            <thead>\n'
                      '              <tr>\n'
                      '                <th>Ngày</th>\n'
                      '                <th>Số đơn</th>\n'
                      '                <th>Số cốc</th>\n'
                      '                <th>Giá trị đơn</th>\n'
                      '              </tr>\n'
                      '            </thead>\n'
                      '\n'
                      '            <tbody id="historyTable">\n'
                      '              <tr>\n'
                      '                <td colspan="4">\n'
                      '                  Đang tải...\n'
                      '                </td>\n'
                      '              </tr>\n'
                      '            </tbody>\n'
                      '\n'
                      '          </table>\n'
                      '\n'
                      '        </div>\n'
                      '\n'
                      '      </section>\n'
                      '\n'
                      '    </section>\n'
                      '\n'
                      '\n'
                      '    <!-- =========================\n'
                      '         ORDERS\n'
                      '    ========================== -->\n'
                      '\n'
                      '    <section\n'
                      '      id="tab-orders"\n'
                      '      class="tab-page"\n'
                      '    >\n'
                      '\n'
                      '      <section class="panel">\n'
                      '\n'
                      '        <div class="section-head">\n'
                      '\n'
                      '          <div>\n'
                      '\n'
                      '            <div class="section-label">\n'
                      '              REALTIME\n'
                      '            </div>\n'
                      '\n'
                      '            <h2>\n'
                      '              Đơn hàng hôm nay\n'
                      '            </h2>\n'
                      '\n'
                      '            <p class="muted">\n'
                      '              Đơn tại quán và giao tận nơi sẽ tự xuất hiện.\n'
                      '            </p>\n'
                      '\n'
                      '          </div>\n'
                      '\n'
                      '          <span class="status-pill online">\n'
                      '            ● Đang theo dõi\n'
                      '          </span>\n'
                      '\n'
                      '        </div>\n'
                      '\n'
                      '        <div\n'
                      '          id="ordersList"\n'
                      '          class="orders-list"\n'
                      '        >\n'
                      '\n'
                      '          <div class="empty-admin">\n'
                      '            Đang tải đơn...\n'
                      '          </div>\n'
                      '\n'
                      '        </div>\n'
                      '\n'
                      '      </section>\n'
                      '\n'
                      '    </section>\n'
                      '\n'
                      '\n'
                      '    <!-- =========================\n'
                      '         MENU\n'
                      '    ========================== -->\n'
                      '\n'
                      '    <section\n'
                      '      id="tab-menu"\n'
                      '      class="tab-page"\n'
                      '    >\n'
                      '\n'
                      '      <section class="panel">\n'
                      '\n'
                      '        <div class="section-head">\n'
                      '\n'
                      '          <div>\n'
                      '\n'
                      '            <div class="section-label">\n'
                      '              MENU\n'
                      '            </div>\n'
                      '\n'
                      '            <h2 id="formTitle">\n'
                      '              Thêm món mới\n'
                      '            </h2>\n'
                      '\n'
                      '            <p class="muted">\n'
                      '              Quản lý món, danh mục, size và topping.\n'
                      '            </p>\n'
                      '\n'
                      '          </div>\n'
                      '\n'
                      '        </div>\n'
                      '\n'
                      '\n'
                      '        <form id="menuForm">\n'
                      '\n'
                      '          <div class="form-grid">\n'
                      '\n'
                      '            <div>\n'
                      '\n'
                      '              <label for="itemId">\n'
                      '                Mã món\n'
                      '              </label>\n'
                      '\n'
                      '              <input\n'
                      '                id="itemId"\n'
                      '                maxlength="30"\n'
                      '                placeholder="CF01"\n'
                      '                required\n'
                      '              >\n'
                      '\n'
                      '            </div>\n'
                      '\n'
                      '\n'
                      '            <div>\n'
                      '\n'
                      '              <label for="itemName">\n'
                      '                Tên món\n'
                      '              </label>\n'
                      '\n'
                      '              <input\n'
                      '                id="itemName"\n'
                      '                maxlength="100"\n'
                      '                placeholder="Cà phê sữa"\n'
                      '                required\n'
                      '              >\n'
                      '\n'
                      '            </div>\n'
                      '\n'
                      '\n'
                      '            <div>\n'
                      '\n'
                      '              <label for="itemCategory">\n'
                      '                Danh mục\n'
                      '              </label>\n'
                      '\n'
                      '              <input\n'
                      '                id="itemCategory"\n'
                      '                maxlength="80"\n'
                      '                placeholder="Cà phê"\n'
                      '                required\n'
                      '              >\n'
                      '\n'
                      '            </div>\n'
                      '\n'
                      '\n'
                      '            <div>\n'
                      '\n'
                      '              <label for="itemDescription">\n'
                      '                Mô tả\n'
                      '              </label>\n'
                      '\n'
                      '              <input\n'
                      '                id="itemDescription"\n'
                      '                maxlength="300"\n'
                      '                placeholder="Cà phê sữa truyền thống"\n'
                      '              >\n'
                      '\n'
