                      '\n'
                      '    <p>\n'
                      '      Chọn món yêu thích và tận hưởng\n'
                      '      một chút thư giãn cùng Cheng Coffee.\n'
                      '    </p>\n'
                      '\n'
                      '\n'
                      '    <div class="welcome-progress">\n'
                      '      <span></span>\n'
                      '    </div>\n'
                      '\n'
                      '\n'
                      '    <small>\n'
                      '      Đang chuẩn bị menu...\n'
                      '    </small>\n'
                      '\n'
                      '  </div>\n'
                      '\n'
                      '</div>\n'
                      '\n'
                      '\n'
                      '<!-- =====================================================\n'
                      '     MÀN HÌNH ĐẶT MÓN THÀNH CÔNG\n'
                      '===================================================== -->\n'
                      '\n'
                      '<div\n'
                      '  id="successScreen"\n'
                      '  class="success-screen"\n'
                      '  hidden\n'
                      '>\n'
                      '\n'
                      '  <div class="success-light success-light-one"></div>\n'
                      '  <div class="success-light success-light-two"></div>\n'
                      '\n'
                      '\n'
                      '  <div class="success-content">\n'
                      '\n'
                      '    <div class="success-icon">\n'
                      '      ✓\n'
                      '    </div>\n'
                      '\n'
                      '\n'
                      '    <div class="success-brand">\n'
                      '      CHENG COFFEE\n'
                      '    </div>\n'
                      '\n'
                      '\n'
                      '    <h1>\n'
                      '      Đặt món thành công\n'
                      '    </h1>\n'
                      '\n'
                      '\n'
                      '    <p class="success-thank">\n'
                      '      Cảm ơn quý khách\n'
                      '    </p>\n'
                      '\n'
                      '\n'
                      '    <p class="success-description">\n'
                      '      Cheng Coffee đã nhận được đơn của bạn.\n'
                      '      Chúng tôi sẽ chuẩn bị trong thời gian sớm nhất.\n'
                      '    </p>\n'
                      '\n'
                      '\n'
                      '    <div class="success-order-box">\n'
                      '\n'
                      '      <span>\n'
                      '        Mã đơn\n'
                      '      </span>\n'
                      '\n'
                      '      <strong id="successOrderId">\n'
                      '        ---\n'
                      '      </strong>\n'
                      '\n'
                      '    </div>\n'
                      '\n'
                      '\n'
                      '    <div\n'
                      '      id="successPaymentHint"\n'
                      '      class="success-payment-hint"\n'
                      '    ></div>\n'
                      '\n'
                      '\n'
                      '    <button\n'
                      '      id="backToMenuBtn"\n'
                      '      class="success-button"\n'
                      '      type="button"\n'
                      '    >\n'
                      '      Về menu\n'
                      '    </button>\n'
                      '\n'
                      '  </div>\n'
                      '\n'
                      '</div>\n'
                      '\n'
                      '\n'
                      '<!-- =====================================================\n'
                      '     HEADER\n'
                      '===================================================== -->\n'
                      '\n'
                      '<header class="hero">\n'
                      '\n'
                      '  <div class="hero-inner">\n'
                      '\n'
                      '    <div>\n'
                      '\n'
                      '      <div class="brand-small">\n'
                      '        CHENG COFFEE\n'
                      '      </div>\n'
                      '\n'
                      '\n'
                      '      <h1>\n'
                      '        Hôm nay bạn muốn uống gì?\n'
                      '      </h1>\n'
                      '\n'
                      '\n'
                      '      <p>\n'
                      '        Chọn món, size và topping.\n'
                      '        Dùng tại quán hoặc giao tận nơi đều được.\n'
                      '      </p>\n'
                      '\n'
                      '    </div>\n'
                      '\n'
                      '\n'
                      '    <a\n'
                      '      href="admin.html"\n'
                      '      class="admin-link"\n'
                      '    >\n'
                      '      Admin\n'
                      '    </a>\n'
                      '\n'
                      '  </div>\n'
                      '\n'
                      '</header>\n'
                      '\n'
                      '\n'
                      '<!-- =====================================================\n'
                      '     MAIN\n'
                      '===================================================== -->\n'
                      '\n'
                      '<main class="main-layout">\n'
                      '\n'
                      '\n'
                      '  <!-- ===================================================\n'
                      '       MENU\n'
                      '  =================================================== -->\n'
                      '\n'
                      '  <section class="menu-area">\n'
                      '\n'
                      '\n'
                      '    <div class="menu-toolbar">\n'
                      '\n'
                      '\n'
                      '      <div>\n'
                      '\n'
                      '        <h2>\n'
                      '          Menu\n'
                      '        </h2>\n'
                      '\n'
                      '        <p id="menuStatus">\n'
                      '          Đang tải menu...\n'
                      '        </p>\n'
                      '\n'
                      '      </div>\n'
                      '\n'
                      '\n'
                      '      <div class="search-box">\n'
                      '\n'
                      '        <span>\n'
                      '          ⌕\n'
                      '        </span>\n'
                      '\n'
                      '        <input\n'
                      '          id="menuSearch"\n'
                      '          type="search"\n'
                      '          placeholder="Tìm món..."\n'
                      '          autocomplete="off"\n'
                      '        >\n'
                      '\n'
                      '      </div>\n'
                      '\n'
                      '    </div>\n'
                      '\n'
                      '\n'
                      '    <!-- DANH MỤC -->\n'
                      '\n'
                      '    <div class="category-bar">\n'
                      '\n'
                      '      <div\n'
                      '        id="categoryNav"\n'
                      '        class="category-nav"\n'
                      '      >\n'
                      '\n'
                      '        <button\n'
                      '          class="category-button active"\n'
                      '          data-category="all"\n'
                      '          type="button"\n'
                      '        >\n'
                      '          Tất cả\n'
                      '        </button>\n'
                      '\n'
                      '      </div>\n'
                      '\n'
                      '    </div>\n'
                      '\n'
                      '\n'
                      '    <!-- DANH SÁCH MÓN -->\n'
                      '\n'
                      '    <div id="menu"></div>\n'
                      '\n'
                      '\n'
                      '  </section>\n'
                      '\n'
                      '\n'
                      '  <!-- ===================================================\n'
                      '       GIỎ HÀNG\n'
                      '  =================================================== -->\n'
                      '\n'
                      '  <aside class="cart-area">\n'
                      '\n'
                      '    <div class="cart-card">\n'
                      '\n'
                      '\n'
                      '      <div class="cart-header">\n'
                      '\n'
                      '        <div>\n'
                      '\n'
                      '          <div class="section-label">\n'
                      '            ĐƠN CỦA BẠN\n'
                      '          </div>\n'
                      '\n'
                      '          <h2>\n'
                      '            Món đã chọn\n'
                      '          </h2>\n'
                      '\n'
                      '        </div>\n'
                      '\n'
                      '\n'
                      '        <span\n'
                      '          id="cartCount"\n'
                      '          class="cart-count"\n'
                      '        >\n'
                      '          0 món\n'
                      '        </span>\n'
                      '\n'
                      '      </div>\n'
                      '\n'
                      '\n'
                      '      <div\n'
                      '        id="cartItems"\n'
                      '        class="cart-items"\n'
                      '      >\n'
                      '\n'
                      '        <div class="empty-cart">\n'
                      '\n'
                      '          <div>\n'
                      '            🧋\n'
                      '          </div>\n'
                      '\n'
                      '          <strong>\n'
                      '            Chưa có món nào\n'
                      '          </strong>\n'
                      '\n'
                      '          <span>\n'
                      '            Chọn một món từ menu để bắt đầu.\n'
                      '          </span>\n'
                      '\n'
                      '        </div>\n'
                      '\n'
                      '      </div>\n'
                      '\n'
                      '\n'
                      '      <div class="divider"></div>\n'
                      '\n'
                      '\n'
                      '      <!-- =================================================\n'
                      '           HÌNH THỨC NHẬN MÓN\n'
                      '      ================================================= -->\n'
                      '\n'
                      '      <section class="checkout-section">\n'
                      '\n'
                      '        <div class="checkout-title">\n'
                      '\n'
                      '          <div>\n'
                      '\n'
                      '            <span class="checkout-label">\n'
                      '              HÌNH THỨC NHẬN MÓN\n'
                      '            </span>\n'
                      '\n'
                      '            <h3>\n'
                      '              Bạn muốn nhận món thế nào?\n'
                      '            </h3>\n'
                      '\n'
                      '          </div>\n'
                      '\n'
                      '        </div>\n'
                      '\n'
                      '\n'
                      '        <div class="fulfillment-options">\n'
                      '\n'
                      '\n'
                      '          <label class="fulfillment-card">\n'
                      '\n'
                      '            <input\n'
                      '              type="radio"\n'
                      '              name="fulfillmentType"\n'
                      '              value="dine_in"\n'
                      '              checked\n'
                      '            >\n'
                      '\n'
                      '            <div class="fulfillment-icon">\n'
                      '              ☕\n'
                      '            </div>\n'
                      '\n'
                      '            <div>\n'
                      '\n'
                      '              <strong>\n'
                      '                Uống tại quán\n'
                      '              </strong>\n'
                      '\n'
                      '              <span>\n'
                      '                Nhập số bàn của bạn\n'
                      '              </span>\n'
                      '\n'
                      '            </div>\n'
                      '\n'
                      '          </label>\n'
                      '\n'
                      '\n'
                      '          <label class="fulfillment-card">\n'
                      '\n'
                      '            <input\n'
                      '              type="radio"\n'
                      '              name="fulfillmentType"\n'
                      '              value="delivery"\n'
                      '            >\n'
                      '\n'
                      '            <div class="fulfillment-icon">\n'
                      '              🛵\n'
                      '            </div>\n'
                      '\n'
                      '            <div>\n'
                      '\n'
                      '              <strong>\n'
                      '                Giao tận nơi\n'
                      '              </strong>\n'
                      '\n'
                      '              <span>\n'
                      '                Ship đến địa chỉ của bạn\n'
                      '              </span>\n'
                      '\n'
                      '            </div>\n'
                      '\n'
                      '          </label>\n'
                      '\n'
                      '\n'
                      '        </div>\n'
                      '\n'
                      '      </section>\n'
                      '\n'
                      '\n'
                      '      <!-- =================================================\n'
                      '           UỐNG TẠI QUÁN\n'
                      '      ================================================= -->\n'
                      '\n'
                      '      <div\n'
                      '        id="dineInFields"\n'
                      '        class="checkout-fields"\n'
                      '      >\n'
                      '\n'
                      '        <div class="field-group">\n'
                      '\n'
                      '          <label for="tableNumber">Số bàn (không bắt buộc)</label>\n'
                      '\n'
                      '          <input\n'
                      '            id="tableNumber"\n'
                      '            maxlength="20"\n'
                      '            placeholder="Có thể để trống"\n'
                      '          >\n'
                      '\n'
                      '        </div>\n'
                      '\n'
                      '      </div>\n'
                      '\n'
                      '\n'
                      '      <!-- =================================================\n'
                      '           GIAO TẬN NƠI\n'
                      '      ================================================= -->\n'
                      '\n'
                      '      <div\n'
                      '        id="deliveryFields"\n'
                      '        class="checkout-fields"\n'
                      '        hidden\n'
                      '      >\n'
                      '\n'
                      '\n'
                      '        <div class="field-group">\n'
                      '\n'
                      '          <label for="customerName">\n'
                      '            Họ và tên\n'
                      '          </label>\n'
                      '\n'
                      '          <input\n'
                      '            id="customerName"\n'
                      '            maxlength="100"\n'
                      '            autocomplete="name"\n'
                      '            placeholder="Nguyễn Văn A"\n'
                      '          >\n'
                      '\n'
                      '        </div>\n'
                      '\n'
                      '\n'
                      '        <div class="field-group">\n'
                      '\n'
                      '          <label for="customerPhone">\n'
                      '            Số điện thoại\n'
                      '          </label>\n'
                      '\n'
                      '          <input\n'
                      '            id="customerPhone"\n'
                      '            maxlength="20"\n'
                      '            inputmode="tel"\n'
                      '            autocomplete="tel"\n'
                      '            placeholder="09xxxxxxxx"\n'
                      '          >\n'
                      '\n'
                      '        </div>\n'
                      '\n'
                      '\n'
                      '        <div class="field-group">\n'
                      '\n'
                      '          <label for="customerAddress">\n'
                      '            Địa chỉ nhận hàng\n'
                      '          </label>\n'
                      '\n'
                      '          <textarea\n'
                      '            id="customerAddress"\n'
                      '            maxlength="300"\n'
                      '            rows="3"\n'
                      '            autocomplete="street-address"\n'
                      '            placeholder="Số nhà, tên đường, phường/xã..."\n'
                      '          ></textarea>\n'
                      '\n'
                      '        </div>\n'
                      '\n'
                      '\n'
                      '        <div class="field-group">\n'
                      '\n'
                      '          <label for="deliveryNote">\n'
                      '            Ghi chú giao hàng\n'
                      '          </label>\n'
                      '\n'
                      '          <textarea\n'
                      '            id="deliveryNote"\n'
                      '            maxlength="200"\n'
                      '            rows="2"\n'
                      '            placeholder="Ví dụ: gọi trước khi tới..."\n'
                      '          ></textarea>\n'
                      '\n'
                      '        </div>\n'
                      '\n'
                      '\n'
                      '      </div>\n'
                      '\n'
                      '\n'
                      '      <!-- =================================================\n'
                      '           GHI CHÚ CHUNG\n'
                      '      ================================================= -->\n'
                      '\n'
                      '      <div class="field-group order-note-group">\n'
                      '\n'
                      '        <label for="orderNote">\n'
                      '          Ghi chú cho đơn\n'
                      '        </label>\n'
                      '\n'
                      '        <textarea\n'
                      '          id="orderNote"\n'
                      '          maxlength="240"\n'
                      '          rows="3"\n'
                      '          placeholder="Ví dụ: làm tất cả ít ngọt..."\n'
                      '        ></textarea>\n'
                      '\n'
                      '        <small>\n'
                      '          Tối đa 240 ký tự\n'
                      '        </small>\n'
                      '\n'
                      '      </div>\n'
                      '\n'
                      '\n'
                      '      <div class="divider"></div>\n'
                      '\n'
                      '\n'
                      '      <!-- =================================================\n'
                      '           PHƯƠNG THỨC THANH TOÁN\n'
                      '      ================================================= -->\n'
                      '\n'
                      '      <section class="checkout-section">\n'
                      '\n'
                      '        <div class="checkout-title">\n'
                      '\n'
                      '          <div>\n'
                      '\n'
                      '            <span class="checkout-label">\n'
                      '              THANH TOÁN\n'
                      '            </span>\n'
                      '\n'
                      '            <h3>\n'
                      '              Phương thức thanh toán\n'
                      '            </h3>\n'
                      '\n'
                      '          </div>\n'
                      '\n'
                      '        </div>\n'
                      '\n'
                      '\n'
                      '        <div class="payment-options">\n'
                      '\n'
                      '\n'
                      '          <label class="payment-card">\n'
                      '\n'
                      '            <input\n'
                      '              type="radio"\n'
                      '              name="paymentMethod"\n'
                      '              value="cash"\n'
                      '              checked\n'
                      '            >\n'
                      '\n'
                      '            <div class="payment-icon">\n'
                      '              💵\n'
                      '            </div>\n'
                      '\n'
                      '            <div>\n'
                      '\n'
                      '              <strong>\n'
                      '                Tiền mặt\n'
                      '              </strong>\n'
                      '\n'
                      '              <span>\n'
                      '                Thanh toán khi nhận món\n'
                      '              </span>\n'
                      '\n'
                      '            </div>\n'
                      '\n'
                      '          </label>\n'
                      '\n'
                      '\n'
                      '          <label class="payment-card">\n'
                      '\n'
                      '            <input\n'
                      '              type="radio"\n'
                      '              name="paymentMethod"\n'
                      '              value="bank_transfer"\n'
                      '            >\n'
                      '\n'
                      '            <div class="payment-icon">\n'
                      '              🏦\n'
                      '            </div>\n'
                      '\n'
                      '            <div>\n'
                      '\n'
                      '              <strong>\n'
                      '                Chuyển khoản\n'
                      '              </strong>\n'
                      '\n'
                      '              <span>\n'
                      '                Quét QR ngân hàng\n'
                      '              </span>\n'
                      '\n'
                      '            </div>\n'
                      '\n'
                      '          </label>\n'
                      '\n'
                      '\n'
                      '        </div>\n'
                      '\n'
                      '      </section>\n'
                      '\n'
                      '\n'
                      '      <!-- =================================================\n'
                      '           BANK TRANSFER\n'
                      '      ================================================= -->\n'
                      '\n'
                      '      <div\n'
                      '        id="bankTransferPanel"\n'
                      '        class="bank-transfer-panel"\n'
                      '        hidden\n'
                      '      >\n'
                      '\n'
                      '        <div class="bank-title">\n'
                      '\n'
                      '          <span>\n'
                      '            THANH TOÁN CHUYỂN KHOẢN\n'
                      '          </span>\n'
                      '\n'
                      '          <h3>\n'
                      '            Quét mã QR\n'
                      '          </h3>\n'
                      '\n'
                      '        </div>\n'
                      '\n'
                      '\n'
                      '        <div class="bank-layout">\n'
                      '\n'
                      '\n'
                      '          <div class="bank-qr-box">\n'
                      '\n'
                      '            <img\n'
                      '              id="bankQrImage"\n'
                      '              src=""\n'
                      '              alt="QR chuyển khoản Cheng Coffee"\n'
                      '              hidden\n'
                      '            >\n'
                      '\n'
                      '\n'
                      '            <div\n'
                      '              id="bankQrPlaceholder"\n'
                      '              class="bank-qr-placeholder"\n'
                      '            >\n'
                      '              QR ngân hàng\n'
                      '            </div>\n'
                      '\n'
                      '          </div>\n'
                      '\n'
                      '\n'
                      '          <div class="bank-details">\n'
                      '\n'
                      '\n'
                      '            <div class="bank-detail">\n'
                      '\n'
                      '              <span>\n'
                      '                Ngân hàng\n'
                      '              </span>\n'
                      '\n'
                      '              <strong id="bankName">\n'
                      '                Đang cập nhật\n'
                      '              </strong>\n'
                      '\n'
                      '            </div>\n'
                      '\n'
                      '\n'
                      '            <div class="bank-detail">\n'
                      '\n'
                      '              <span>\n'
                      '                Chủ tài khoản\n'
                      '              </span>\n'
                      '\n'
                      '              <strong id="bankAccountName">\n'
                      '                Đang cập nhật\n'
                      '              </strong>\n'
                      '\n'
                      '            </div>\n'
                      '\n'
                      '\n'
                      '            <div class="bank-detail">\n'
                      '\n'
                      '              <span>\n'
                      '                Số tài khoản\n'
                      '              </span>\n'
                      '\n'
                      '              <strong id="bankAccountNumber">\n'
                      '                Đang cập nhật\n'
                      '              </strong>\n'
                      '\n'
                      '            </div>\n'
                      '\n'
                      '\n'
                      '            <div class="bank-detail">\n'
                      '\n'
                      '              <span>\n'
                      '                Hướng dẫn\n'
                      '              </span>\n'
                      '\n'
                      '              <strong id="bankInstructions">\n'
                      '                Vui lòng chuyển đúng số tiền của đơn.\n'
                      '              </strong>\n'
                      '\n'
                      '            </div>\n'
                      '\n'
                      '\n'
                      '          </div>\n'
                      '\n'
                      '        </div>\n'
                      '\n'
                      '\n'
                      '        <div class="bank-warning">\n'
                      '\n'
                      '          <strong>\n'
                      '            Lưu ý:\n'
                      '          </strong>\n'
                      '\n'
                      '          Sau khi chuyển khoản,\n'
                      '          bạn vẫn cần bấm\n'
                      '          <b>ĐẶT MÓN</b>\n'
                      '          để gửi đơn cho Cheng Coffee.\n'
                      '\n'
                      '        </div>\n'
                      '\n'
                      '      </div>\n'
                      '\n'
                      '\n'
                      '      <!-- =================================================\n'
                      '           TOTAL\n'
                      '      ================================================= -->\n'
                      '\n'
                      '      <div class="total-row">\n'
                      '\n'
                      '        <span>\n'
                      '          Tổng cộng\n'
                      '        </span>\n'
                      '\n'
                      '        <strong id="total">\n'
                      '          0đ\n'
                      '        </strong>\n'
                      '\n'
                      '      </div>\n'
                      '\n'
                      '\n'
                      '      <button\n'
                      '        id="orderBtn"\n'
                      '        class="order-button"\n'
                      '        type="button"\n'
                      '      >\n'
                      '        ĐẶT MÓN\n'
                      '      </button>\n'
                      '\n'
                      '\n'
                      '      <p\n'
                      '        id="message"\n'
                      '        class="order-message"\n'
                      '      ></p>\n'
                      '\n'
                      '\n'
                      '    </div>\n'
                      '\n'
                      '  </aside>\n'
                      '\n'
                      '\n'
                      '</main>\n'
                      '\n'
                      '\n'
                      '<!-- =====================================================\n'
                      '     MODAL SIZE + TOPPING\n'
                      '===================================================== -->\n'
                      '\n'
                      '<div\n'
                      '  id="optionModal"\n'
                      '  class="option-modal"\n'
                      '  hidden\n'
                      '>\n'
                      '\n'
                      '  <div class="option-dialog">\n'
                      '\n'
                      '\n'
                      '    <button\n'
                      '      id="closeOptionModal"\n'
                      '      class="dialog-close"\n'
                      '      type="button"\n'
                      '      aria-label="Đóng"\n'
                      '    >\n'
                      '      ×\n'
                      '    </button>\n'
                      '\n'
                      '\n'
                      '    <div class="dialog-label">\n'
                      '      TÙY CHỌN MÓN\n'
                      '    </div>\n'
                      '\n'
                      '\n'
                      '    <h2 id="optionItemName"></h2>\n'
                      '\n'
                      '\n'
                      '    <p\n'
                      '      id="optionItemDescription"\n'
                      '      class="dialog-description"\n'
                      '    ></p>\n'
                      '\n'
                      '\n'
                      '    <!-- SIZE -->\n'
                      '\n'
                      '    <section class="option-section">\n'
                      '\n'
                      '      <div class="option-title">\n'
                      '\n'
                      '        <h3>\n'
                      '          Chọn size\n'
                      '        </h3>\n'
                      '\n'
                      '        <span>\n'
                      '          Bắt buộc\n'
                      '        </span>\n'
                      '\n'
